import {redirect} from "next/navigation";
import {createSupabaseServerClient} from "../../../lib/supabase/server";
import {decodeDisplayText} from "../../../lib/text";
const catLabels:Record<string,string>={venues:"Venue",photography:"Photography",videography:"Videography",planners:"Planning",florists:"Florals",catering:"Catering",djs:"DJ / Music","hair-makeup":"Hair & Makeup",cakes:"Cake",rentals:"Rentals"};
function score(v:any,c:any){let s=55;if(c.wedding_city&&(v.city===c.wedding_city||v.service_cities?.includes(c.wedding_city)))s+=18;if(c.wedding_style&&v.wedding_styles?.includes(c.wedding_style))s+=12;if(c.guest_count&&v.guest_capacity_max&&c.guest_count<=v.guest_capacity_max&&c.guest_count>=(v.guest_capacity_min||0))s+=7;return Math.min(99,s)}
export default async function MatchOpportunities(){const db=await createSupabaseServerClient();const {data:{user}}=await db.auth.getUser();if(!user)redirect("/vendor/login");const {data:v}=await db.from("vendor_profiles").select("*").eq("user_id",user.id).single();if(!v)redirect("/vendor/dashboard");if(!["professional","premium"].includes(v.plan))return <main className="section"><div className="container narrow"><span className="eyebrow">Match Opportunities</span><h1>Meet couples who fit what you do.</h1><p>Browsing opted-in couple matches is available with Pro and Premium.</p><a className="btn primary" href="/for-vendors#membership">Compare plans</a></div></main>;const {data:couples}=await db.from("couple_profiles").select("user_id,wedding_date,wedding_budget,guest_count,wedding_city,wedding_style,wedding_priorities").eq("vendor_discoverable",true).limit(100);const {data:sent}=await db.from("vendor_match_introductions").select("couple_user_id").eq("vendor_id",v.id);const sentIds=new Set((sent||[]).map((x:any)=>x.couple_user_id));const rows=(couples||[]).filter((c:any)=>!sentIds.has(c.user_id)).map((c:any)=>({...c,score:score(v,c)})).sort((a:any,b:any)=>b.score-a.score);return <main><section className="pagehero"><div className="container"><span className="eyebrow">Match Opportunities</span><h1>Couples looking for someone like you. 👋</h1><p className="meta">Only opted-in planning details are shown. Names, emails and phone numbers stay private.</p></div></section><section className="section"><div className="container"><div className="matchOpportunityGrid">{rows.length?rows.map((c:any)=><article className="matchOpportunityCard" key={c.user_id}><span className="matchScore">{c.score}% fit</span><h2>💍 {c.wedding_date?new Date(c.wedding_date+"T12:00:00").toLocaleDateString("en-US",{month:"long",year:"numeric"}):"Date flexible"} · {decodeDisplayText(c.wedding_city||"Portland")}</h2><p>{c.guest_count?`${c.guest_count} guests · `:""}{decodeDisplayText(c.wedding_style||"Style still taking shape")}</p>{c.wedding_budget&&<p className="meta">Overall wedding budget: ${Number(c.wedding_budget).toLocaleString()}</p>}<form action="/api/vendor/match-introduction" method="post"><input type="hidden" name="couple_user_id" value={c.user_id}/><textarea name="message" rows={3} maxLength={300} placeholder="Optional: a quick, personal note about why you could be a great fit."/><button className="btn primary">Send a little wave 👋</button></form></article>):<div className="emptyPlanning"><span>♡</span><h3>No new matches right now.</h3><p>We'll keep this simple: check back as more couples opt in.</p></div>}</div></div></section></main>}
